import re

_PLAIN_RE = re.compile(r"[0-9]+")
_DURATION_RE = re.compile(
    r"(?=.)"
    r"(?:([0-9]+)d)?"
    r"(?:([0-9]+)h)?"
    r"(?:([0-9]+)m)?"
    r"(?:([0-9]+)s)?"
)


def parse_duration(s: str) -> int:
    if _PLAIN_RE.fullmatch(s):
        return int(s)

    m = _DURATION_RE.fullmatch(s)
    if m is None:
        raise ValueError(f"invalid duration: {s!r}")

    days, hours, minutes, seconds = (
        int(g) if g is not None else 0 for g in m.groups()
    )
    return days * 86400 + hours * 3600 + minutes * 60 + seconds

def merge_ranges(ranges: list) -> list:
    cleaned = []
    for start, end in ranges:
        if start > end:
            raise ValueError(f"invalid range ({start}, {end}): start > end")
        if start < end:
            cleaned.append((start, end))

    cleaned.sort()

    merged = []
    for start, end in cleaned:
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1] = (merged[-1][0], end)
        else:
            merged.append((start, end))

    return merged

def semver_compare(a: str, b: str) -> int:
    def cmp(x, y):
        return (x > y) - (x < y)

    def parse(v):
        v = v.split('+', 1)[0]  # build metadata is ignored
        if '-' in v:
            core, pre = v.split('-', 1)
            pre_ids = pre.split('.')
        else:
            core, pre_ids = v, None
        nums = tuple(int(p) for p in core.split('.'))
        return nums, pre_ids

    def cmp_ident(x, y):
        x_num, y_num = x.isdigit(), y.isdigit()
        if x_num and y_num:
            return cmp(int(x), int(y))
        if x_num:  # numeric is lower than alphanumeric
            return -1
        if y_num:
            return 1
        return cmp(x, y)  # ASCII order

    core_a, pre_a = parse(a)
    core_b, pre_b = parse(b)

    c = cmp(core_a, core_b)
    if c:
        return c

    # No pre-release has higher precedence than any pre-release
    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1
    if pre_b is None:
        return -1

    for x, y in zip(pre_a, pre_b):
        c = cmp_ident(x, y)
        if c:
            return c

    # All compared identifiers equal: shorter list is lower
    return cmp(len(pre_a), len(pre_b))

def parse_csv_line(line: str) -> list:
    if line == "":
        return [""]

    fields = []
    i = 0
    n = len(line)

    while True:
        if i < n and line[i] == '"':
            # Quoted field
            i += 1
            buf = []
            while True:
                if i >= n:
                    raise ValueError("unterminated quoted field")
                c = line[i]
                if c == '"':
                    if i + 1 < n and line[i + 1] == '"':
                        buf.append('"')
                        i += 2
                    else:
                        i += 1  # closing quote
                        break
                else:
                    buf.append(c)
                    i += 1
            if i < n and line[i] != ',':
                raise ValueError(
                    f"unexpected character {line[i]!r} after closing quote"
                )
            fields.append("".join(buf))
        else:
            # Unquoted field
            start = i
            while i < n and line[i] != ',':
                if line[i] == '"':
                    raise ValueError("quote inside unquoted field")
                i += 1
            fields.append(line[start:i])

        if i >= n:
            break
        # line[i] is a comma separator
        i += 1

    return fields

def _trunc_div(a: int, b: int) -> int:
    if b == 0:
        raise ZeroDivisionError("division by zero")
    q = abs(a) // abs(b)
    return q if (a < 0) == (b < 0) else -q


def eval_expr(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("expression must be a string")

    # Tokenize
    tokens = []
    i, n = 0, len(s)
    while i < n:
        c = s[i]
        if c.isspace():
            i += 1
        elif '0' <= c <= '9':
            j = i
            while j < n and '0' <= s[j] <= '9':
                j += 1
            tokens.append(('num', int(s[i:j])))
            i = j
        elif c in '+-*/()':
            tokens.append((c, None))
            i += 1
        else:
            raise ValueError(f"invalid character {c!r} at position {i}")

    pos = 0

    def peek():
        return tokens[pos][0] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    # Grammar:
    #   expr    := term (('+' | '-') term)*
    #   term    := unary (('*' | '/') unary)*
    #   unary   := ('+' | '-') unary | primary
    #   primary := NUMBER | '(' expr ')'

    def parse_expr():
        value = parse_term()
        while peek() in ('+', '-'):
            op = advance()[0]
            rhs = parse_term()
            value = value + rhs if op == '+' else value - rhs
        return value

    def parse_term():
        value = parse_unary()
        while peek() in ('*', '/'):
            op = advance()[0]
            rhs = parse_unary()
            value = value * rhs if op == '*' else _trunc_div(value, rhs)
        return value

    def parse_unary():
        if peek() in ('+', '-'):
            op = advance()[0]
            v = parse_unary()
            return -v if op == '-' else v
        return parse_primary()

    def parse_primary():
        t = peek()
        if t == 'num':
            return advance()[1]
        if t == '(':
            advance()
            v = parse_expr()
            if peek() != ')':
                raise ValueError("missing closing parenthesis")
            advance()
            return v
        if t is None:
            raise ValueError("unexpected end of input")
        raise ValueError(f"unexpected token {t!r}")

    if not tokens:
        raise ValueError("empty expression")

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("unexpected trailing input")
    return result

def justify(words: list, width: int) -> list:
    if not words:
        return []

    def build_line(line_words, is_last):
        if is_last or len(line_words) == 1:
            line = " ".join(line_words)
            return line + " " * (width - len(line))

        total_chars = sum(len(w) for w in line_words)
        gaps = len(line_words) - 1
        spaces = width - total_chars
        base, extra = divmod(spaces, gaps)

        parts = []
        for i, w in enumerate(line_words[:-1]):
            parts.append(w)
            parts.append(" " * (base + (1 if i < extra else 0)))
        parts.append(line_words[-1])
        return "".join(parts)

    lines = []
    current = []
    current_len = 0  # total length of words plus single spaces between them

    for w in words:
        needed = len(w) if not current else current_len + 1 + len(w)
        if needed <= width:
            current.append(w)
            current_len = needed
        else:
            lines.append(build_line(current, False))
            current = [w]
            current_len = len(w)

    if current:
        lines.append(build_line(current, True))

    return lines

import heapq


def topo_order(deps: dict) -> list:
    graph = {}      # prerequisite -> set of nodes that depend on it
    indegree = {}   # node -> number of distinct unmet prerequisites

    for node, prereqs in deps.items():
        graph.setdefault(node, set())
        indegree.setdefault(node, 0)
        for p in prereqs:
            graph.setdefault(p, set())
            indegree.setdefault(p, 0)
            if node not in graph[p]:
                graph[p].add(node)
                indegree[node] += 1

    heap = [n for n, d in indegree.items() if d == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        n = heapq.heappop(heap)
        order.append(n)
        for m in graph[n]:
            indegree[m] -= 1
            if indegree[m] == 0:
                heapq.heappush(heap, m)

    if len(order) != len(indegree):
        raise ValueError("cycle detected in dependencies")

    return order

def glob_match(pattern: str, name: str) -> bool:
    # Tokenize the pattern.
    tokens = []
    i = 0
    m = len(pattern)
    while i < m:
        c = pattern[i]
        if c == '*':
            tokens.append(('star',))
            i += 1
        elif c == '?':
            tokens.append(('any',))
            i += 1
        elif c == '[':
            j = pattern.find(']', i + 1)
            if j == -1:
                # No closing bracket: '[' is a literal.
                tokens.append(('lit', '['))
                i += 1
            else:
                content = pattern[i + 1:j]
                negate = False
                if content.startswith('!'):
                    negate = True
                    content = content[1:]
                singles = set()
                ranges = []
                k = 0
                while k < len(content):
                    if k + 2 < len(content) and content[k + 1] == '-':
                        lo, hi = content[k], content[k + 2]
                        ranges.append((lo, hi))
                        k += 3
                    else:
                        singles.add(content[k])
                        k += 1
                tokens.append(('set', negate, singles, ranges))
                i = j + 1
        else:
            tokens.append(('lit', c))
            i += 1

    def token_matches(tok, ch):
        kind = tok[0]
        if kind == 'any':
            return True
        if kind == 'lit':
            return ch == tok[1]
        if kind == 'set':
            _, negate, singles, ranges = tok
            found = ch in singles or any(lo <= ch <= hi for lo, hi in ranges)
            return found != negate
        return False

    n = len(name)
    # Set of positions in `name` reachable after consuming tokens so far.
    current = {0}
    for tok in tokens:
        if not current:
            return False
        if tok[0] == 'star':
            start = min(current)
            current = set(range(start, n + 1))
        else:
            nxt = set()
            for p in current:
                if p < n and token_matches(tok, name[p]):
                    nxt.add(p + 1)
            current = nxt
    return n in current

