def _below_thousand(n: int) -> str:
    """Words for 0 <= n < 1000, without a leading or trailing scale word."""
    parts = []
    hundreds, rest = divmod(n, 100)
    if hundreds:
        parts.append(ONES[hundreds] + " hundred")
    if rest:
        if rest < 20:
            parts.append(ONES[rest])
        else:
            tens, ones = divmod(rest, 10)
            word = TENS[tens]
            if ones:
                word += "-" + ONES[ones]
            parts.append(word)
    return " ".join(parts)


def to_words(n: int) -> str:
    if n < 0 or n >= 10**12:
        raise ValueError("n must be in the range 0 <= n < 10**12")
    if n == 0:
        return "zero"

    groups = []
    index = 0
    while n > 0:
        n, group = divmod(n, 1000)
        if group:
            groups.append(_below_thousand(group) + (" " + SCALES[index] if SCALES[index] else ""))
        index += 1

    return " ".join(reversed(groups))

from datetime import date, timedelta


def business_days(start: str, end: str, holidays: list) -> int:
    s = date.fromisoformat(start)
    e = date.fromisoformat(end)
    if e < s:
        return -business_days(end, start, holidays)

    hol = {date.fromisoformat(h) for h in holidays}

    count = 0
    d = s
    while d < e:
        if d.weekday() < 5 and d not in hol:
            count += 1
        d += timedelta(days=1)
    return count

def json_pointer_get(doc, pointer: str):
    if pointer == "":
        return doc
    if not pointer.startswith("/"):
        raise ValueError("JSON Pointer must be empty or start with '/'")

    current = doc
    for raw in pointer[1:].split("/"):
        token = raw.replace("~1", "/").replace("~0", "~")

        if isinstance(current, dict):
            if token not in current:
                raise KeyError(token)
            current = current[token]
        elif isinstance(current, list):
            if (
                not token
                or any(c not in "0123456789" for c in token)
                or (len(token) > 1 and token[0] == "0")
            ):
                raise KeyError(token)
            idx = int(token)
            if idx >= len(current):
                raise KeyError(token)
            current = current[idx]
        else:
            raise KeyError(token)

    return current

from collections import deque


class RateLimiter:
    def __init__(self, limit: int, window: float):
        self.limit = limit
        self.window = window
        self._allowed = deque()

    def allow(self, t: float) -> bool:
        cutoff = t - self.window
        while self._allowed and self._allowed[0] <= cutoff:
            self._allowed.popleft()
        if len(self._allowed) < self.limit:
            self._allowed.append(t)
            return True
        return False

import re

_CANONICAL_ROMAN = re.compile(
    r"^M{0,3}"
    r"(CM|CD|D?C{0,3})"
    r"(XC|XL|L?X{0,3})"
    r"(IX|IV|V?I{0,3})$"
)

_VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def roman_to_int(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("Input must be a string")
    if not s:
        raise ValueError("Empty string is not a valid Roman numeral")
    if not _CANONICAL_ROMAN.fullmatch(s):
        raise ValueError(f"Not a canonical Roman numeral in range 1-3999: {s!r}")

    total = 0
    n = len(s)
    for i, ch in enumerate(s):
        value = _VALUES[ch]
        if i + 1 < n and value < _VALUES[s[i + 1]]:
            total -= value
        else:
            total += value

    if not 1 <= total <= 3999:
        raise ValueError(f"Value out of range 1-3999: {s!r}")
    return total

def apply_ledger(balance: int, transactions: list) -> tuple:
    fees_charged = 0
    declined = 0

    for txn in transactions:
        try:
            kind, amount = txn
        except (TypeError, ValueError):
            raise ValueError(f"malformed transaction: {txn!r}")

        if isinstance(amount, bool) or not isinstance(amount, int) or amount <= 0:
            raise ValueError(f"amount must be a positive int, got {amount!r}")

        if kind == "dep":
            balance += amount
        elif kind == "wd":
            if balance - amount >= 0:
                balance -= amount
            else:
                declined += 1
                if fees_charged < 3:
                    balance -= 2500
                    fees_charged += 1
        else:
            raise ValueError(f"unknown transaction kind: {kind!r}")

    return (balance, declined)

def compress_ranges(nums: list) -> str:
    if not nums:
        return ""

    def fmt(start: int, end: int) -> str:
        if end - start >= 2:
            return f"{start}-{end}"
        if end - start == 1:
            return f"{start},{end}"
        return str(start)

    vals = sorted(set(nums))
    parts = []
    start = prev = vals[0]
    for v in vals[1:]:
        if v == prev + 1:
            prev = v
        else:
            parts.append(fmt(start, prev))
            start = prev = v
    parts.append(fmt(start, prev))
    return ",".join(parts)

def normalize_path(p: str) -> str:
    absolute = p.startswith("/")
    stack = []
    for seg in p.split("/"):
        if seg == "" or seg == ".":
            continue
        if seg == "..":
            if stack and stack[-1] != "..":
                stack.pop()
            elif not absolute:
                stack.append("..")
            # absolute path: ".." at root stays at root
        else:
            stack.append(seg)
    if absolute:
        return "/" + "/".join(stack)
    return "/".join(stack) or "."

import re

_PLAIN_RE = re.compile(r"[0-9]+")
_PARTS_RE = re.compile(
    r"(?:(?P<d>[0-9]+)d)?"
    r"(?:(?P<h>[0-9]+)h)?"
    r"(?:(?P<m>[0-9]+)m)?"
    r"(?:(?P<s>[0-9]+)s)?"
)
_UNIT_SECONDS = {"d": 86400, "h": 3600, "m": 60, "s": 1}


def parse_duration(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError(f"invalid duration: {s!r}")
    if not s:
        raise ValueError("invalid duration: empty string")

    if _PLAIN_RE.fullmatch(s):
        return int(s)

    match = _PARTS_RE.fullmatch(s)
    if match is None:
        raise ValueError(f"invalid duration: {s!r}")

    total = 0
    for unit, factor in _UNIT_SECONDS.items():
        value = match.group(unit)
        if value is not None:
            total += int(value) * factor
    return total

def merge_ranges(ranges: list) -> list:
    """Merge half-open integer ranges [start, end).

    Overlapping and touching ranges are merged. Empty ranges are dropped.
    Raises ValueError if any range has start > end.
    """
    cleaned = []
    for r in ranges:
        try:
            start, end = r
        except (TypeError, ValueError):
            raise ValueError(f"invalid range: {r!r}")
        if start > end:
            raise ValueError(f"invalid range: start {start!r} > end {end!r}")
        if start < end:
            cleaned.append((start, end))

    cleaned.sort()

    merged = []
    for start, end in cleaned:
        if merged and start <= merged[-1][1]:
            last_start, last_end = merged[-1]
            if end > last_end:
                merged[-1] = (last_start, end)
        else:
            merged.append((start, end))

    return merged

def semver_compare(a: str, b: str) -> int:
    def parse(v: str):
        v = v.split("+", 1)[0]
        if "-" in v:
            core, pre = v.split("-", 1)
            pre_ids = pre.split(".")
        else:
            core, pre_ids = v, None
        major, minor, patch = (int(x) for x in core.split("."))
        return (major, minor, patch), pre_ids

    def cmp(x, y) -> int:
        return (x > y) - (x < y)

    def cmp_ident(x: str, y: str) -> int:
        xn, yn = x.isdigit(), y.isdigit()
        if xn and yn:
            return cmp(int(x), int(y))
        if xn:
            return -1
        if yn:
            return 1
        return cmp(x, y)

    core_a, pre_a = parse(a)
    core_b, pre_b = parse(b)

    c = cmp(core_a, core_b)
    if c:
        return c

    if pre_a is None and pre_b is None:
        return 0
    if pre_a is None:
        return 1
    if pre_b is None:
        return -1

    for x, y in zip(pre_a, pre_b):
        c = cmp_ident(x, y)
        if c:
            return c
    return cmp(len(pre_a), len(pre_b))

