import heapq


def topo_order(deps: dict) -> list:
    nodes = set(deps)
    for prereqs in deps.values():
        nodes.update(prereqs)

    dependents = {n: set() for n in nodes}
    indegree = {n: 0 for n in nodes}

    for node, prereqs in deps.items():
        for p in set(prereqs):
            if p == node:
                raise ValueError(f"cycle detected: {node!r} depends on itself")
            dependents[p].add(node)
            indegree[node] += 1

    heap = [n for n in nodes if indegree[n] == 0]
    heapq.heapify(heap)

    order = []
    while heap:
        n = heapq.heappop(heap)
        order.append(n)
        for d in dependents[n]:
            indegree[d] -= 1
            if indegree[d] == 0:
                heapq.heappush(heap, d)

    if len(order) != len(nodes):
        raise ValueError("cycle detected")

    return order

