from datetime import date


def business_days(start: str, end: str, holidays: list) -> int:
    s = date.fromisoformat(start)
    e = date.fromisoformat(end)
    if e < s:
        return -business_days(end, start, holidays)

    total_days = (e - s).days
    full_weeks, extra = divmod(total_days, 7)
    count = full_weeks * 5
    start_wd = s.weekday()
    for i in range(extra):
        if (start_wd + i) % 7 < 5:
            count += 1

    seen = set()
    for h in holidays:
        hd = date.fromisoformat(h) if isinstance(h, str) else h
        if hd in seen:
            continue
        seen.add(hd)
        if s <= hd < e and hd.weekday() < 5:
            count -= 1

    return count

import re

_INDEX_RE = re.compile(r"0|[1-9][0-9]*")


def json_pointer_get(doc, pointer: str):
    """Resolve an RFC 6901 JSON Pointer against a document."""
    if not isinstance(pointer, str):
        raise TypeError("pointer must be a string")
    if pointer == "":
        return doc
    if not pointer.startswith("/"):
        raise ValueError(f"Invalid JSON Pointer {pointer!r}: must be empty or start with '/'")

    current = doc
    for raw in pointer[1:].split("/"):
        token = raw.replace("~1", "/").replace("~0", "~")

        if isinstance(current, dict):
            if token not in current:
                raise KeyError(token)
            current = current[token]
        elif isinstance(current, list):
            if not _INDEX_RE.fullmatch(token):
                raise KeyError(token)
            index = int(token)
            if index >= len(current):
                raise KeyError(token)
            current = current[index]
        else:
            raise KeyError(token)

    return current

from collections import deque


class RateLimiter:
    def __init__(self, limit: int, window: float):
        self.limit = limit
        self.window = window
        self._allowed = deque()

    def allow(self, t: float) -> bool:
        if self.limit <= 0:
            return False
        q = self._allowed
        boundary = t - self.window
        while q and q[0] <= boundary:
            q.popleft()
        if len(q) < self.limit:
            q.append(t)
            return True
        return False

import re

_ROMAN_RE = re.compile(
    r"M{0,3}"
    r"(CM|CD|D?C{0,3})"
    r"(XC|XL|L?X{0,3})"
    r"(IX|IV|V?I{0,3})"
)

_VALUES = {"I": 1, "V": 5, "X": 10, "L": 50, "C": 100, "D": 500, "M": 1000}


def roman_to_int(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError(f"Expected a string, got {type(s).__name__}")
    if not s or _ROMAN_RE.fullmatch(s) is None:
        raise ValueError(f"Invalid Roman numeral: {s!r}")

    total = 0
    for i, ch in enumerate(s):
        value = _VALUES[ch]
        if i + 1 < len(s) and value < _VALUES[s[i + 1]]:
            total -= value
        else:
            total += value

    if not 1 <= total <= 3999:
        raise ValueError(f"Roman numeral out of range: {s!r}")
    return total

def apply_ledger(balance: int, transactions: list) -> tuple:
    FEE = 2500
    MAX_FEES = 3

    balance_now = balance
    declined = 0
    fees_charged = 0

    for tx in transactions:
        if not isinstance(tx, (tuple, list)) or len(tx) != 2:
            raise ValueError(f"malformed transaction: {tx!r}")
        kind, amount = tx

        if isinstance(amount, bool) or not isinstance(amount, int) or amount <= 0:
            raise ValueError(f"amount must be a positive int: {amount!r}")

        if kind == "dep":
            balance_now += amount
        elif kind == "wd":
            if balance_now - amount >= 0:
                balance_now -= amount
            else:
                declined += 1
                if fees_charged < MAX_FEES:
                    balance_now -= FEE
                    fees_charged += 1
        else:
            raise ValueError(f"unknown transaction kind: {kind!r}")

    return (balance_now, declined)

def compress_ranges(nums: list) -> str:
    values = sorted(set(nums))
    if not values:
        return ""

    parts = []
    i = 0
    n = len(values)
    while i < n:
        j = i
        while j + 1 < n and values[j + 1] == values[j] + 1:
            j += 1
        length = j - i + 1
        if length >= 3:
            parts.append(f"{values[i]}-{values[j]}")
        else:
            parts.extend(str(values[k]) for k in range(i, j + 1))
        i = j + 1

    return ",".join(parts)

def normalize_path(p: str) -> str:
    is_abs = p.startswith("/")
    stack = []
    for seg in p.split("/"):
        if seg == "" or seg == ".":
            continue
        if seg == "..":
            if stack and stack[-1] != "..":
                stack.pop()
            elif not is_abs:
                stack.append("..")
            # absolute path at root: ignore
        else:
            stack.append(seg)
    joined = "/".join(stack)
    if is_abs:
        return "/" + joined
    return joined or "."

import re
from datetime import datetime, time, timedelta

_DIGITS = re.compile(r"[0-9]+")
_TIME_FMT = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}")

# (name, lowest value, highest value)
_BOUNDS = [
    ("minute", 0, 59),
    ("hour", 0, 23),
    ("day of month", 1, 31),
    ("month", 1, 12),
    ("day of week", 0, 7),
]


def _to_int(text, name):
    if not _DIGITS.fullmatch(text):
        raise ValueError(f"invalid {name} value: {text!r}")
    return int(text)


def _parse_field(text, lo, hi, name):
    """Return (set of allowed values, restricted flag)."""
    if text == "*":
        return set(range(lo, hi + 1)), False

    def check(v):
        if not lo <= v <= hi:
            raise ValueError(f"{name} value {v} out of range {lo}-{hi}")
        return v

    def parse_range(base):
        parts = base.split("-")
        if len(parts) != 2:
            raise ValueError(f"invalid {name} range: {base!r}")
        a = check(_to_int(parts[0], name))
        b = check(_to_int(parts[1], name))
        if a > b:
            raise ValueError(f"{name} range start greater than end: {base!r}")
        return a, b

    values = set()
    for item in text.split(","):
        if item == "":
            raise ValueError(f"empty item in {name} field: {text!r}")
        if "/" in item:
            base, _, step_text = item.partition("/")
            step = _to_int(step_text, name)
            if step < 1:
                raise ValueError(f"step must be >= 1 in {name} field: {item!r}")
            if base == "*":
                a, b = lo, hi
            elif "-" in base:
                a, b = parse_range(base)
            else:
                a, b = check(_to_int(base, name)), hi
            values.update(range(a, b + 1, step))
        elif "-" in item:
            a, b = parse_range(item)
            values.update(range(a, b + 1))
        else:
            values.add(check(_to_int(item, name)))

    if name == "day of week":
        # 0 and 7 both mean Sunday
        values = {0 if v == 7 else v for v in values}
    return values, True


def _parse_expr(expr):
    if not isinstance(expr, str):
        raise ValueError("expr must be a string")
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError(f"expected 5 fields, got {len(fields)}")

    parsed = []
    for text, (name, lo, hi) in zip(fields, _BOUNDS):
        parsed.append(_parse_field(text, lo, hi, name))

    (minutes, _), (hours, _), (doms, dom_r), (months, _), (dows, dow_r) = parsed
    return minutes, hours, doms, months, dows, dom_r, dow_r


def _day_matches(day, doms, dows, dom_restricted, dow_restricted):
    dom_ok = day.day in doms
    cron_dow = (day.weekday() + 1) % 7  # Sunday = 0, Monday = 1
    dow_ok = cron_dow in dows
    if dom_restricted and dow_restricted:
        return dom_ok or dow_ok
    return dom_ok and dow_ok


def _add_years(dt, years):
    try:
        return dt.replace(year=dt.year + years)
    except ValueError:
        # February 29 in a non-leap target year
        return dt.replace(year=dt.year + years, day=28)


def cron_next(expr: str, after: str) -> str:
    minutes, hours, doms, months, dows, dom_r, dow_r = _parse_expr(expr)

    if not isinstance(after, str) or not _TIME_FMT.fullmatch(after):
        raise ValueError(f"invalid time: {after!r}")
    try:
        start = datetime.strptime(after, "%Y-%m-%d %H:%M")
    except ValueError as e:
        raise ValueError(f"invalid time: {after!r}") from e

    horizon = _add_years(start, 5)
    t = start + timedelta(minutes=1)  # strictly after `after`
    sorted_hours = sorted(hours)
    sorted_minutes = sorted(minutes)

    day = t.date()
    while day <= horizon.date():
        if day.month in months and _day_matches(day, doms, dows, dom_r, dow_r):
            on_start_day = (day == t.date())
            for h in sorted_hours:
                for m in sorted_minutes:
                    if on_start_day and (h, m) < (t.hour, t.minute):
                        continue
                    candidate = datetime.combine(day, time(h, m))
                    if candidate > horizon:
                        raise ValueError(
                            "no matching time within the next 5 years"
                        )
                    return candidate.strftime("%Y-%m-%d %H:%M")
        day += timedelta(days=1)

    raise ValueError("no matching time within the next 5 years")

import calendar
import datetime as dt

_CONVENTIONS = {"none", "following", "preceding", "modified_following"}


def roll_date(date: str, months: int, convention: str, holidays: list) -> str:
    if convention not in _CONVENTIONS:
        raise ValueError(f"Unknown convention: {convention!r}")

    start = dt.date.fromisoformat(date)

    # Step 1: add months
    total = start.year * 12 + (start.month - 1) + months
    year, month_index = divmod(total, 12)
    month = month_index + 1
    target_last_day = calendar.monthrange(year, month)[1]

    start_last_day = calendar.monthrange(start.year, start.month)[1]
    if start.day == start_last_day:
        day = target_last_day  # end-of-month rule
    else:
        day = min(start.day, target_last_day)
    result = dt.date(year, month, day)

    # Step 2: business day adjustment
    holiday_set = {
        h if isinstance(h, dt.date) else dt.date.fromisoformat(h)
        for h in holidays
    }

    def is_business_day(d: dt.date) -> bool:
        return d.weekday() < 5 and d not in holiday_set

    def next_business_day(d: dt.date) -> dt.date:
        while not is_business_day(d):
            d += dt.timedelta(days=1)
        return d

    def previous_business_day(d: dt.date) -> dt.date:
        while not is_business_day(d):
            d -= dt.timedelta(days=1)
        return d

    if convention == "none" or is_business_day(result):
        return result.isoformat()

    if convention == "following":
        adjusted = next_business_day(result)
    elif convention == "preceding":
        adjusted = previous_business_day(result)
    else:  # modified_following
        candidate = next_business_day(result)
        if candidate.month != result.month:
            adjusted = previous_business_day(result)
        else:
            adjusted = candidate

    return adjusted.isoformat()

import re

_NAME_RE = re.compile(r'[A-Za-z_][A-Za-z0-9_]*')


def shell_split(line: str, env: dict) -> list:
    words = []
    buf = []
    in_word = False
    i = 0
    n = len(line)

    def expand_var(pos):
        # line[pos] == '$'. Returns (text, new_pos).
        if pos + 1 < n and line[pos + 1] == '{':
            end = line.find('}', pos + 2)
            if end == -1:
                raise ValueError("unterminated ${")
            name = line[pos + 2:end]
            if not _NAME_RE.fullmatch(name):
                raise ValueError("invalid variable name in ${...}: %r" % name)
            return env.get(name, ""), end + 1
        m = _NAME_RE.match(line, pos + 1)
        if m:
            return env.get(m.group(0), ""), m.end()
        return "$", pos + 1  # literal '$'

    while i < n:
        c = line[i]

        if c == ' ' or c == '\t':
            if in_word:
                words.append(''.join(buf))
                buf = []
                in_word = False
            i += 1

        elif c == "'":
            in_word = True
            end = line.find("'", i + 1)
            if end == -1:
                raise ValueError("unterminated single quote")
            buf.append(line[i + 1:end])
            i = end + 1

        elif c == '"':
            in_word = True
            i += 1
            while True:
                if i >= n:
                    raise ValueError("unterminated double quote")
                ch = line[i]
                if ch == '"':
                    i += 1
                    break
                if ch == '\\':
                    if i + 1 >= n:
                        raise ValueError("unterminated double quote")
                    nxt = line[i + 1]
                    if nxt in '"\\$':
                        buf.append(nxt)
                    else:
                        buf.append('\\' + nxt)
                    i += 2
                elif ch == '$':
                    text, i = expand_var(i)
                    buf.append(text)
                else:
                    buf.append(ch)
                    i += 1

        elif c == '\\':
            in_word = True
            if i + 1 >= n:
                raise ValueError("trailing backslash")
            buf.append(line[i + 1])
            i += 2

        elif c == '$':
            text, i = expand_var(i)
            if text == "$" and i == 0:
                pass  # unreachable guard, kept for clarity
            if text:
                in_word = True
            buf.append(text)

        else:
            in_word = True
            buf.append(c)
            i += 1

    if in_word:
        words.append(''.join(buf))

    return words

import re

_TAG_RE = re.compile(r"\{\{\{(.*?)\}\}\}|\{\{(.*?)\}\}", re.DOTALL)
_NAME_RE = re.compile(r"\.|@?\w+(?:\.\w+)*")
_BLOCK_RE = re.compile(r"#(if|each)\s+(\S+)")
_ESCAPES = {
    ord("&"): "&amp;",
    ord("<"): "&lt;",
    ord(">"): "&gt;",
    ord('"'): "&quot;",
    ord("'"): "&#39;",
}
_TAG_TEXT = {"else": "{{else}}", "endif": "{{/if}}", "endeach": "{{/each}}"}


def _check_name(s):
    s = s.strip()
    if not _NAME_RE.fullmatch(s):
        raise ValueError(f"invalid name: {s!r}")
    return s


def _classify(content):
    s = content.strip()
    if s == "else":
        return ("else",)
    if s == "/if":
        return ("endif",)
    if s == "/each":
        return ("endeach",)
    if s.startswith("#"):
        m = _BLOCK_RE.fullmatch(s)
        if not m:
            raise ValueError(f"invalid block tag: {{{{{s}}}}}")
        return (m.group(1), _check_name(m.group(2)))
    if s == "" or s.startswith("/"):
        raise ValueError(f"invalid tag: {{{{{s}}}}}")
    return ("var", _check_name(s), False)


def _tokenize(template):
    tokens = []
    last = 0
    for m in _TAG_RE.finditer(template):
        if m.start() > last:
            tokens.append(("text", template[last:m.start()]))
        if m.group(1) is not None:
            tokens.append(("var", _check_name(m.group(1)), True))
        else:
            tokens.append(_classify(m.group(2)))
        last = m.end()
    if last < len(template):
        tokens.append(("text", template[last:]))
    return tokens


def _parse(tokens, pos, enders):
    nodes = []
    while pos < len(tokens):
        token = tokens[pos]
        kind = token[0]
        if kind in enders:
            return nodes, pos
        if kind in _TAG_TEXT:
            raise ValueError(f"unexpected or mismatched {_TAG_TEXT[kind]}")
        if kind in ("text", "var"):
            nodes.append(token)
            pos += 1
        elif kind == "if":
            then_nodes, pos = _parse(tokens, pos + 1, ("else", "endif"))
            if pos >= len(tokens):
                raise ValueError("unclosed {{#if}} block")
            else_nodes = []
            if tokens[pos][0] == "else":
                else_nodes, pos = _parse(tokens, pos + 1, ("endif",))
                if pos >= len(tokens):
                    raise ValueError("unclosed {{#if}} block")
            nodes.append(("if", token[1], then_nodes, else_nodes))
            pos += 1  # skip {{/if}}
        elif kind == "each":
            body, pos = _parse(tokens, pos + 1, ("endeach",))
            if pos >= len(tokens):
                raise ValueError("unclosed {{#each}} block")
            nodes.append(("each", token[1], body))
            pos += 1  # skip {{/each}}
        else:
            raise ValueError(f"unknown token: {kind!r}")
    return nodes, pos


def _lookup(name, scopes, root):
    """Return the value for name, or None if missing."""
    if name == ".":
        return scopes[-1]["item"] if scopes else None
    parts = name.split(".")
    first = parts[0]
    if name == "@index":
        return scopes[-1]["index"] if scopes else None

    value = None
    found = False
    for frame in reversed(scopes):  # innermost item first
        item = frame["item"]
        if isinstance(item, dict) and first in item:
            value = item[first]
            found = True
            break
    if not found and first in root:
        value = root[first]
        found = True
    if not found:
        return None

    for part in parts[1:]:
        if isinstance(value, dict) and part in value:
            value = value[part]
        else:
            return None
    return value


def _to_text(value, raw):
    if value is None:
        return ""
    text = str(value)
    return text if raw else text.translate(_ESCAPES)


def _render(nodes, scopes, root, out):
    for node in nodes:
        kind = node[0]
        if kind == "text":
            out.append(node[1])
        elif kind == "var":
            out.append(_to_text(_lookup(node[1], scopes, root), node[2]))
        elif kind == "if":
            value = _lookup(node[1], scopes, root)
            _render(node[2] if value else node[3], scopes, root, out)
        elif kind == "each":
            items = _lookup(node[1], scopes, root)
            if items is None:
                continue
            for index, item in enumerate(items):
                scopes.append({"item": item, "index": index})
                try:
                    _render(node[2], scopes, root, out)
                finally:
                    scopes.pop()


def render(template: str, ctx: dict) -> str:
    tokens = _tokenize(template)
    nodes, _ = _parse(tokens, 0, ())
    out = []
    _render(nodes, [], ctx if ctx is not None else {}, out)
    return "".join(out)

def eval_expr(s: str) -> int:
    if not isinstance(s, str):
        raise ValueError("input must be a string")

    tokens = []
    i, n = 0, len(s)
    while i < n:
        c = s[i]
        if c in " \t\r\n":
            i += 1
        elif c.isdigit() and c in "0123456789":
            j = i
            while j < n and s[j] in "0123456789":
                j += 1
            tokens.append(("num", int(s[i:j])))
            i = j
        elif c in "+-*/()":
            tokens.append(("op", c))
            i += 1
        else:
            raise ValueError(f"invalid character {c!r} at position {i}")

    pos = 0

    def peek():
        return tokens[pos] if pos < len(tokens) else None

    def advance():
        nonlocal pos
        tok = peek()
        if tok is None:
            raise ValueError("unexpected end of expression")
        pos += 1
        return tok

    def div_trunc(a, b):
        if b == 0:
            raise ZeroDivisionError("division by zero")
        q = abs(a) // abs(b)
        return q if (a >= 0) == (b >= 0) else -q

    def parse_expr():
        val = parse_term()
        while True:
            tok = peek()
            if tok == ("op", "+"):
                advance()
                val = val + parse_term()
            elif tok == ("op", "-"):
                advance()
                val = val - parse_term()
            else:
                return val

    def parse_term():
        val = parse_unary()
        while True:
            tok = peek()
            if tok == ("op", "*"):
                advance()
                val = val * parse_unary()
            elif tok == ("op", "/"):
                advance()
                val = div_trunc(val, parse_unary())
            else:
                return val

    def parse_unary():
        sign = 1
        while True:
            tok = peek()
            if tok == ("op", "+"):
                advance()
            elif tok == ("op", "-"):
                advance()
                sign = -sign
            else:
                break
        val = parse_primary()
        return -val if sign < 0 else val

    def parse_primary():
        tok = advance()
        if tok[0] == "num":
            return tok[1]
        if tok == ("op", "("):
            val = parse_expr()
            if advance() != ("op", ")"):
                raise ValueError("expected ')'")
            return val
        raise ValueError(f"unexpected token {tok[1]!r}")

    if not tokens:
        raise ValueError("empty expression")
    result = parse_expr()
    if pos != len(tokens):
        raise ValueError(f"unexpected token {tokens[pos][1]!r}")
    return result

from datetime import datetime, timedelta, date


def _parse_int(s: str) -> int:
    if not s or not s.isascii() or not s.isdigit():
        raise ValueError(f"invalid number: {s!r}")
    return int(s)


def _parse_field(field: str, lo: int, hi: int) -> set:
    if not isinstance(field, str) or field == "":
        raise ValueError("empty field")
    values = set()
    for item in field.split(","):
        if item == "":
            raise ValueError("empty list item")
        step = 1
        has_step = False
        if "/" in item:
            base, step_s = item.split("/", 1)
            step = _parse_int(step_s)
            if step < 1:
                raise ValueError("step must be >= 1")
            has_step = True
        else:
            base = item

        if base == "*":
            start, end = lo, hi
        elif "-" in base:
            a_s, b_s = base.split("-", 1)
            start, end = _parse_int(a_s), _parse_int(b_s)
            if not (lo <= start <= hi) or not (lo <= end <= hi):
                raise ValueError(f"value out of range in {item!r}")
            if start > end:
                raise ValueError(f"invalid range {item!r}")
        else:
            start = _parse_int(base)
            if not (lo <= start <= hi):
                raise ValueError(f"value out of range in {item!r}")
            end = hi if has_step else start

        values.update(range(start, end + 1, step))
    return values


def cron_next(expr: str, after: str) -> str:
    if not isinstance(expr, str):
        raise ValueError("expression must be a string")
    fields = expr.split()
    if len(fields) != 5:
        raise ValueError("cron expression must have exactly 5 fields")

    minutes = sorted(_parse_field(fields[0], 0, 59))
    hours = sorted(_parse_field(fields[1], 0, 23))
    doms = _parse_field(fields[2], 1, 31)
    months = _parse_field(fields[3], 1, 12)
    dows = {0 if d == 7 else d for d in _parse_field(fields[4], 0, 7)}

    dom_star = fields[2] == "*"
    dow_star = fields[4] == "*"

    if not isinstance(after, str):
        raise ValueError("after must be a string")
    try:
        base = datetime.strptime(after, "%Y-%m-%d %H:%M")
    except (ValueError, TypeError) as e:
        raise ValueError(f"invalid time: {after!r}") from e

    start = base + timedelta(minutes=1)
    try:
        limit = base.replace(year=base.year + 5)
    except ValueError:  # Feb 29 -> Feb 28
        limit = base.replace(year=base.year + 5, day=28)

    def day_matches(d: date) -> bool:
        if d.month not in months:
            return False
        dom_ok = d.day in doms
        dow_ok = ((d.weekday() + 1) % 7) in dows
        if dom_star and dow_star:
            return True
        if dom_star:
            return dow_ok
        if dow_star:
            return dom_ok
        return dom_ok or dow_ok

    day = start.date()
    first = True
    while day <= limit.date():
        if day_matches(day):
            for h in hours:
                if first and h < start.hour:
                    continue
                for m in minutes:
                    if first and h == start.hour and m < start.minute:
                        continue
                    cand = datetime(day.year, day.month, day.day, h, m)
                    if cand > limit:
                        raise ValueError("no match within the next 5 years")
                    return cand.strftime("%Y-%m-%d %H:%M")
        first = False
        day += timedelta(days=1)

    raise ValueError("no match within the next 5 years")

import calendar
from datetime import date as _date, timedelta

_CONVENTIONS = {"none", "following", "preceding", "modified_following"}


def roll_date(date: str, months: int, convention: str, holidays: list) -> str:
    if convention not in _CONVENTIONS:
        raise ValueError(f"Unknown convention: {convention!r}")

    start = _date.fromisoformat(date)

    # Step 1: add months
    total = start.year * 12 + (start.month - 1) + months
    year, month = divmod(total, 12)
    month += 1
    if not (_date.min.year <= year <= _date.max.year):
        raise ValueError("Resulting date out of range")

    target_len = calendar.monthrange(year, month)[1]
    start_len = calendar.monthrange(start.year, start.month)[1]
    if start.day == start_len:
        day = target_len
    else:
        day = min(start.day, target_len)
    result = _date(year, month, day)

    # Step 2: business day adjustment
    holiday_set = set()
    for h in holidays or []:
        if isinstance(h, _date):
            holiday_set.add(h)
        else:
            holiday_set.add(_date.fromisoformat(str(h)))

    def is_business(d: _date) -> bool:
        return d.weekday() < 5 and d not in holiday_set

    def next_business(d: _date) -> _date:
        while not is_business(d):
            d += timedelta(days=1)
        return d

    def prev_business(d: _date) -> _date:
        while not is_business(d):
            d -= timedelta(days=1)
        return d

    if convention == "none" or is_business(result):
        return result.isoformat()

    if convention == "following":
        result = next_business(result)
    elif convention == "preceding":
        result = prev_business(result)
    else:  # modified_following
        candidate = next_business(result)
        if candidate.month != result.month or candidate.year != result.year:
            candidate = prev_business(result)
        result = candidate

    return result.isoformat()

import re

_NAME_START = re.compile(r"[A-Za-z_]")
_NAME = re.compile(r"[A-Za-z_][A-Za-z0-9_]*")


def _expand(line, i, env):
    """Parse a variable reference starting at line[i] == '$'.

    Returns (value_or_None, new_index). A value of None means the '$'
    is a literal dollar sign.
    """
    n = len(line)
    j = i + 1
    if j < n and line[j] == "{":
        close = line.find("}", j + 1)
        if close == -1:
            raise ValueError("unterminated ${")
        name = line[j + 1:close]
        if not _NAME.fullmatch(name):
            raise ValueError("bad substitution: ${%s}" % name)
        return str(env.get(name, "")), close + 1
    if j < n and _NAME_START.match(line[j]):
        m = _NAME.match(line, j)
        name = m.group(0)
        return str(env.get(name, "")), m.end()
    return None, i + 1


def shell_split(line: str, env: dict) -> list:
    words = []
    buf = []
    in_word = False
    i = 0
    n = len(line)

    while i < n:
        c = line[i]

        if c in " \t":
            if in_word:
                words.append("".join(buf))
                buf = []
                in_word = False
            i += 1

        elif c == "\\":
            if i + 1 >= n:
                raise ValueError("trailing backslash")
            buf.append(line[i + 1])
            in_word = True
            i += 2

        elif c == "'":
            close = line.find("'", i + 1)
            if close == -1:
                raise ValueError("unterminated single quote")
            buf.append(line[i + 1:close])
            in_word = True
            i = close + 1

        elif c == '"':
            in_word = True
            i += 1
            closed = False
            while i < n:
                d = line[i]
                if d == '"':
                    closed = True
                    i += 1
                    break
                if d == "\\":
                    if i + 1 >= n:
                        break  # unterminated quote
                    nxt = line[i + 1]
                    if nxt in '"\\$':
                        buf.append(nxt)
                    else:
                        buf.append("\\" + nxt)
                    i += 2
                elif d == "$":
                    val, i = _expand(line, i, env)
                    buf.append("$" if val is None else val)
                else:
                    buf.append(d)
                    i += 1
            if not closed:
                raise ValueError("unterminated double quote")

        elif c == "$":
            val, i = _expand(line, i, env)
            if val is None:
                buf.append("$")
                in_word = True
            elif val:
                buf.append(val)
                in_word = True

        else:
            buf.append(c)
            in_word = True
            i += 1

    if in_word:
        words.append("".join(buf))
    return words

import re

_TOKEN_RE = re.compile(r"\{\{\{\s*(.*?)\s*\}\}\}|\{\{\s*(.*?)\s*\}\}", re.S)
_MISSING = object()


def _escape(s):
    return (s.replace("&", "&amp;")
             .replace("<", "&lt;")
             .replace(">", "&gt;")
             .replace('"', "&quot;")
             .replace("'", "&#39;"))


def _parse(template):
    root = []
    # stack entries: dict with keys type, name, nodes (current target list), node
    stack = []
    current = root
    pos = 0
    for m in _TOKEN_RE.finditer(template):
        if m.start() > pos:
            current.append(("text", template[pos:m.start()]))
        pos = m.end()
        if m.group(1) is not None:
            current.append(("var", m.group(1).strip(), False))
            continue
        tag = m.group(2).strip()
        if tag.startswith("#"):
            parts = tag[1:].split(None, 1)
            kind = parts[0] if parts else ""
            name = parts[1].strip() if len(parts) > 1 else ""
            if kind == "if":
                node = ["if", name, [], None]
                current.append(node)
                stack.append({"type": "if", "node": node, "has_else": False})
                current = node[2]
            elif kind == "each":
                node = ["each", name, []]
                current.append(node)
                stack.append({"type": "each", "node": node})
                current = node[2]
            else:
                raise ValueError("Unknown block tag: %r" % tag)
        elif tag.startswith("/"):
            kind = tag[1:].strip()
            if kind not in ("if", "each"):
                raise ValueError("Unknown closing tag: %r" % tag)
            if not stack:
                raise ValueError("Stray closing tag: %r" % tag)
            top = stack.pop()
            if top["type"] != kind:
                raise ValueError("Mismatched closing tag: expected /%s, got /%s"
                                 % (top["type"], kind))
            current = stack[-1]["cur"] if stack else root
        elif tag == "else":
            if not stack or stack[-1]["type"] != "if" or stack[-1]["has_else"]:
                raise ValueError("Stray {{else}}")
            top = stack[-1]
            top["has_else"] = True
            top["node"][3] = []
            current = top["node"][3]
        else:
            current.append(("var", tag, True))
        if stack:
            stack[-1]["cur"] = current
    if pos < len(template):
        current.append(("text", template[pos:]))
    if stack:
        raise ValueError("Unclosed block: #%s" % stack[-1]["type"])
    return root


def _lookup(name, frames):
    if name == ".":
        return frames[-1][0]
    if name == "@index":
        for item, idx in reversed(frames):
            if idx is not None:
                return idx
        return None
    if not name:
        return None
    parts = name.split(".")
    first = parts[0]
    value = _MISSING
    for item, _ in reversed(frames):
        if isinstance(item, dict) and first in item:
            value = item[first]
            break
    if value is _MISSING:
        return None
    for p in parts[1:]:
        if isinstance(value, dict) and p in value:
            value = value[p]
        else:
            return None
    return value


def _render_nodes(nodes, frames, out):
    for node in nodes:
        kind = node[0]
        if kind == "text":
            out.append(node[1])
        elif kind == "var":
            value = _lookup(node[1], frames)
            s = "" if value is None else str(value)
            out.append(_escape(s) if node[2] else s)
        elif kind == "if":
            value = _lookup(node[1], frames)
            if value:
                _render_nodes(node[2], frames, out)
            elif node[3] is not None:
                _render_nodes(node[3], frames, out)
        elif kind == "each":
            value = _lookup(node[1], frames)
            if value is None:
                continue
            if isinstance(value, dict):
                items = list(value.values())
            elif isinstance(value, (str, bytes)):
                items = [value]
            else:
                try:
                    items = list(value)
                except TypeError:
                    items = [value]
            for i, item in enumerate(items):
                frames.append((item, i))
                try:
                    _render_nodes(node[2], frames, out)
                finally:
                    frames.pop()


def render(template: str, ctx: dict) -> str:
    tree = _parse(template)
    out = []
    _render_nodes(tree, [(ctx if ctx is not None else {}, None)], out)
    return "".join(out)
